/**
 * Method names and typed ScVal encoders for sisonke-escrow (lib.rs).
 * tests/contract-spec.test.ts proves each encoder produces the same XDR as
 * the contract's own spec (web/contract, generated by scripts/bindings.sh).
 */
import { nativeToScVal, xdr } from "@stellar/stellar-sdk";
import type { PartyRole } from "./types";

export const sc = {
  u64: (n: bigint | number) => nativeToScVal(BigInt(n), { type: "u64" }),
  u32: (n: number) => nativeToScVal(n, { type: "u32" }),
  i128: (n: bigint) => nativeToScVal(n, { type: "i128" }),
  address: (a: string) => nativeToScVal(a, { type: "address" }),
  string: (s: string) => nativeToScVal(s, { type: "string" }),
  symbol: (s: string) => nativeToScVal(s, { type: "symbol" }),
  none: () => xdr.ScVal.scvVoid(),
  /** Option<Address>: Some(x) encodes as x itself. */
  optAddress: (a: string | null) => (a ? nativeToScVal(a, { type: "address" }) : xdr.ScVal.scvVoid()),
  /** Unit enum variant: a vec holding the variant's symbol. */
  partyRole: (r: PartyRole) => xdr.ScVal.scvVec([xdr.ScVal.scvSymbol(r)]),
  u64Vec: (ids: bigint[]) => xdr.ScVal.scvVec(ids.map((id) => nativeToScVal(id, { type: "u64" }))),
};

export type WriteMethod =
  | "create"
  | "create_and_fund"
  | "fund"
  | "release"
  | "refund"
  | "reclaim"
  | "dispute"
  | "resolve"
  | "cancel"
  | "extend_escrow_ttl"
  | "migrate";

export type ReadMethod = "info" | "get_escrow" | "get_escrows" | "party_escrow_count" | "party_escrow_ids";

export const WRITE_METHODS: readonly WriteMethod[] = [
  "create",
  "create_and_fund",
  "fund",
  "release",
  "refund",
  "reclaim",
  "dispute",
  "resolve",
  "cancel",
  "extend_escrow_ttl",
  "migrate",
];

export interface CreateArgs {
  payer: string;
  recipient: string;
  arbiter: string | null;
  amount: bigint;
  deadline: number | bigint;
  title: string;
}

/** create / create_and_fund. `terms_hash` is always None in this phase. */
export const encodeCreate = (a: CreateArgs): xdr.ScVal[] => [
  sc.address(a.payer),
  sc.address(a.recipient),
  sc.optAddress(a.arbiter),
  sc.i128(a.amount),
  sc.u64(a.deadline),
  sc.string(a.title),
  sc.none(),
];

export const encode = {
  create: encodeCreate,
  create_and_fund: encodeCreate,
  id: (id: bigint) => [sc.u64(id)],
  dispute: (id: bigint, by: string) => [sc.u64(id), sc.address(by)],
  resolve: (id: bigint, recipientAmount: bigint) => [sc.u64(id), sc.i128(recipientAmount)],
  none: (): xdr.ScVal[] => [],
  getEscrows: (ids: bigint[]) => [sc.u64Vec(ids)],
  partyCount: (party: string, role: PartyRole) => [sc.address(party), sc.partyRole(role)],
  partyIds: (party: string, role: PartyRole, page: number) => [sc.address(party), sc.partyRole(role), sc.u32(page)],
};
